from branch import freeze
from run import lab
base=lab.read(lab.OUT/'i1-whale-station/config.json')
style=' An exquisitely detailed surrealist oil painting, dream logic, luminous jewel-colored enamel against deep velvet shadows. Monumental readable silhouettes, delicate engraved textures, sharp reflected highlights and dimensional shading. Broad cinematic composition, dramatic near and far forms, rich colors separated by dark negative space.'
stages=[(6,'rails-on-the-whale','The immense ivory whale carries a little red steam train along its curved back toward a huge crimson eclipse on the right. Two golden rails continue over the whale\'s forehead and long nose, curving upward toward the glowing red circle. The whale\'s calm black eye remains near the lower left. Behind the train, the old station is partly cropped at the upper left. Dark blue ocean lies below, and open night sky surrounds the red destination.'),(8,'bridge-growing','The ivory whale\'s long forehead and nose extend into a sweeping white railway bridge across the night sky. Golden rails follow the bridge toward the enormous crimson moon at the right. A small red steam train moves along the ridge, trailing a silver ribbon of smoke. The whale\'s large calm eye remains in the curved white stone at the lower left, where its skin is becoming carved arches. The bridge has open dark spaces beneath it, suspended above a deep indigo sea.'),(10,'moonward-bridge','A slender white railway viaduct curves upward across a vast indigo night toward an enormous glowing red moon. A little vermilion steam train travels on the golden rails. The bridge\'s nearest arch at the lower left has the carved shape of a whale\'s head with one calm dark eye; farther arches grow smaller toward the moon. Inside the red circle a warm amber railway doorway is beginning to appear. Long silver smoke from the train links the bridge to the luminous moon.'),(13,'moon-station','A small red steam train follows a narrow ivory railway bridge into a glowing amber doorway in an enormous crimson moon. The moon\'s surface is red enamel, with fine gold seams like a clock face around the entrance. A station window shines above the doorway. Curved ivory arches sweep in from the lower left across open dark blue space, with a faint carved whale eye on the nearest support. The red train and warm doorway remain the clear focus, while the old ocean is far below.')]
phrases=[p for p in base['phrases'] if p['start']<=5.5]
phrases.extend([dict(start=5.5,duration=10,zoom=.50,turn=-15,travel=[-.20,.06],center=[1.05,.42],radius=2.4),dict(start=11,duration=10,zoom=-.15,turn=20,travel=[.08,-.05],center=[.9,.5],radius=4)])
noise=[(6,.6),(6.5,.65),(7,.70),(7.5,.73),(8,.75),(8.5,.75),(9,.66),(9.5,.6),(10,.68),(10.5,.74),(11,.78),(11.5,.76),(12,.65),(12.5,.56),(13,.63),(13.5,.71),(14,.76),(14.5,.68),(15,.55),(15.5,.4)]
freeze('i1-whale-station','i2-bridge-to-the-moon',132,16,[dict(at=t,name=n,prompt=p+style) for t,n,p in stages],[dict(at=t,noise=n) for t,n in noise],phrases)
